export interface IconButtonControlOptions {
    /** Material Design Icons class for the glyph, e.g. 'mdi-fullscreen'. */
    icon: string;
    title: string;
    onClick: () => void;
    /** Leaflet corner to dock in. Defaults to 'topleft'. */
    position?: L.ControlPosition;
    /** Extra classes for the bar, on top of the shared leaflet-bar styling. */
    className?: string;
    /**
     * Called once with the finished container. For controls that must show,
     * hide or observe their own button after it exists.
     */
    onReady?: (container: HTMLElement) => void;
}

/**
 * A single-button `leaflet-bar` control styled like Leaflet's own zoom
 * buttons.
 *
 * Every icon button on our maps -- locate, kiosk, sidebar toggle, and the
 * widget's maximize toggle -- is this same bar with a different glyph and
 * click handler, so the markup lives here and callers bring only behavior.
 */
export function createIconButtonControl(opts: IconButtonControlOptions): L.Control {
    const IconButtonControl = L.Control.extend({
        options: { position: opts.position || 'topleft' },
        onAdd: function (): HTMLElement {
            const classes = 'leaflet-control-zoom leaflet-bar' +
                            (opts.className ? ' ' + opts.className : '');
            const container = L.DomUtil.create('div', classes);
            const link = L.DomUtil.create('a', '', container) as HTMLAnchorElement;
            link.href = '#';
            link.title = opts.title;
            L.DomUtil.create('i', 'mdi ' + opts.icon, link);
            link.style.display = 'flex';
            link.style.alignItems = 'center';
            link.style.justifyContent = 'center';
            link.style.fontSize = '18px';

            L.DomEvent.disableClickPropagation(container);
            L.DomEvent.on(link, 'click', function (e: Event) {
                L.DomEvent.preventDefault(e);
                opts.onClick();
            });

            if (opts.onReady) opts.onReady(container);
            return container;
        },
    });
    return new IconButtonControl();
}

/**
 * Stop a Bootstrap modal from shifting the page sideways as it opens.
 *
 * Bootstrap takes the scrollbar away (`overflow: hidden` on body) and adds an
 * equal `padding-right` to replace the width it assumes it just reclaimed.
 * NetBox reserves that width permanently instead, with `scrollbar-gutter:
 * stable` on :root above 992px, so hiding the scrollbar reclaims nothing and
 * the padding is pure surplus -- the content jumps left on open and back on
 * close.
 *
 * Releasing the gutter while the modal is up makes Bootstrap's assumption
 * true rather than overriding its arithmetic: the width it reclaims is the
 * width it pays back. That also degrades to a no-op if NetBox ever drops the
 * gutter (their code carries a TODO to, once Tabler #2271 ships), where
 * fighting the padding with !important would start causing the very shift it
 * was added to prevent.
 *
 * `show`/`hidden` rather than `shown`/`hide`: Bootstrap adjusts the scrollbar
 * after firing `show` and restores it before firing `hidden`, so this brackets
 * its work from outside.
 */
export function bindModalScrollbarGutter(modal: HTMLElement): void {
    const root = document.documentElement;
    modal.addEventListener('show.bs.modal', function () {
        root.style.scrollbarGutter = 'auto';
    });
    modal.addEventListener('hidden.bs.modal', function () {
        root.style.scrollbarGutter = '';
    });
}

// ---------------------------------------------------------------------------
// Utility helpers
// ---------------------------------------------------------------------------

/**
 * Representative point for any layer type.
 *
 * Markers answer getLatLng(); paths (polylines, and the polygon a Structure
 * with a footprint geometry becomes) only have bounds.
 */
export function layerCenter(layer: L.Layer): L.LatLng {
    const marker = layer as L.Marker;
    if (typeof marker.getLatLng === 'function') return marker.getLatLng();
    return (layer as L.Polyline).getBounds().getCenter();
}

interface DimmablePath extends L.Path {
    _preDimStyle?: { opacity?: number; fillOpacity?: number };
}

/**
 * Fade `layer` to `opacity`, or restore it when `opacity` is null.
 *
 * Markers fade via setOpacity; paths -- polylines and the polygon a Structure
 * with a footprint geometry becomes -- fade via setStyle, remembering the
 * values they carried before the first dim.
 */
export function setLayerDimmed(layer: L.Layer, opacity: number | null): void {
    const marker = layer as L.Marker;
    if (typeof marker.setOpacity === 'function') {
        marker.setOpacity(opacity == null ? 1 : opacity);
        return;
    }
    const path = layer as DimmablePath;
    if (typeof path.setStyle !== 'function') return;

    if (opacity == null) {
        const orig = path._preDimStyle;
        delete path._preDimStyle;
        path.setStyle({
            opacity: orig && orig.opacity != null ? orig.opacity : 1,
            fillOpacity: orig && orig.fillOpacity != null ? orig.fillOpacity : 0.2,
        });
        return;
    }
    if (!path._preDimStyle) {
        const opts = (path.options || {}) as L.PathOptions;
        path._preDimStyle = { opacity: opts.opacity, fillOpacity: opts.fillOpacity };
    }
    path.setStyle({ opacity: opacity, fillOpacity: opacity });
}

export function esc(text: string): string {
    const el = document.createElement('span');
    el.textContent = text;
    return el.innerHTML;
}

export function titleCase(str: string): string {
    return (str || '').replace(/_/g, ' ').replace(/\b\w/g, function (c: string) { return c.toUpperCase(); });
}

export function getCookie(name: string): string | null {
    const value = '; ' + document.cookie;
    const parts = value.split('; ' + name + '=');
    if (parts.length === 2) return parts.pop()!.split(';').shift() || null;
    return null;
}

export function bboxParam(map: L.Map): string {
    const b = map.getBounds();
    return b.getWest() + ',' + b.getSouth() + ',' + b.getEast() + ',' + b.getNorth();
}

export function debounce(fn: () => void, delay: number): () => void {
    let timer: ReturnType<typeof setTimeout>;
    return function () {
        clearTimeout(timer);
        timer = setTimeout(fn, delay);
    };
}

function ringCentroid(ring: GeoJSON.Position[] | undefined): GeoJSON.Position | null {
    if (!ring || ring.length < 4) return null;
    let area = 0, cx = 0, cy = 0;
    for (let i = 0; i < ring.length - 1; i++) {
        const [x0, y0] = ring[i];
        const [x1, y1] = ring[i + 1];
        const cross = x0 * y1 - x1 * y0;
        area += cross;
        cx += (x0 + x1) * cross;
        cy += (y0 + y1) * cross;
    }
    if (area === 0) {
        // Degenerate ring (zero area): fall back to the vertex average.
        const n = ring.length - 1;
        let sx = 0, sy = 0;
        for (let i = 0; i < n; i++) { sx += ring[i][0]; sy += ring[i][1]; }
        return [sx / n, sy / n];
    }
    return [cx / (3 * area), cy / (3 * area)];
}

/**
 * Map anchor for a feature geometry: the point itself, or the centroid of a
 * polygon footprint. Shared by every map view that must place a single
 * marker for a feature that may carry an area geometry -- the reference
 * layer's read-only structure markers and the main data layer's collapsed
 * footprints alike. Null means "cannot anchor, skip".
 */
export function featureAnchor(geometry: GeoJSON.Geometry): GeoJSON.Position | null {
    if (geometry.type === 'Point') return (geometry as GeoJSON.Point).coordinates;
    if (geometry.type === 'Polygon') {
        return ringCentroid((geometry as GeoJSON.Polygon).coordinates[0]);
    }
    if (geometry.type === 'MultiPolygon') {
        const first = (geometry as GeoJSON.MultiPolygon).coordinates[0];
        return first ? ringCentroid(first[0]) : null;
    }
    return null;
}

export function haversine(lat1: number, lon1: number, lat2: number, lon2: number): number {
    const R = 6371000;
    const p1 = lat1 * Math.PI / 180;
    const p2 = lat2 * Math.PI / 180;
    const dp = (lat2 - lat1) * Math.PI / 180;
    const dl = (lon2 - lon1) * Math.PI / 180;
    const a = Math.sin(dp / 2) * Math.sin(dp / 2) +
              Math.cos(p1) * Math.cos(p2) * Math.sin(dl / 2) * Math.sin(dl / 2);
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}
